                double resTol = (double)8 * Consts.doubleSqrtEps;
                double maxRelRes = (double)0;
                for (int t = 0; t < kOut; t++)
                {
                    double res = math.abs(betaLast * ws.BsvdWs.U[pDone - 1, t]);
                    double relRes = res / (sigma0 + Consts.doubleEpsilon);
                    if (relRes > maxRelRes) maxRelRes = relRes;
                }
                converged = (maxRelRes < resTol);
            }

            // Fill top kOut triplets.
            unsafe
            {
                double* UL_ptr   = ws.UL.Data.Ptr;
                double* VL_ptr   = ws.VL.Data.Ptr;
                double* uBuf_ptr = ws.uBuf.Data.Ptr;
                double* vBuf_ptr = ws.vBuf.Data.Ptr;

                for (int t = 0; t < kOut; t++)
                {
                    Sk[t] = ws.BsvdWs.S[t];

                    // uBuf = sum_l P[l,t] * UL[l,:]
                    UnsafeUtility.MemClear(uBuf_ptr, (long)m * UnsafeUtility.SizeOf<double>());
                    for (int l = 0; l < pDone; l++)
                        UnsafeOP.axpy(uBuf_ptr, UL_ptr + l * m, ws.BsvdWs.U[l, t], m);
                    for (int i = 0; i < m; i++) Uk[i, t] = uBuf_ptr[i];

                    // vBuf = sum_l Q[l,t] * VL[l,:]
                    UnsafeUtility.MemClear(vBuf_ptr, (long)n * UnsafeUtility.SizeOf<double>());
                    for (int l = 0; l < pDone; l++)
                        UnsafeOP.axpy(vBuf_ptr, VL_ptr + l * n, ws.BsvdWs.V[l, t], n);
                    for (int i = 0; i < n; i++) Vk[i, t] = vBuf_ptr[i];
                }
            }

            // Zero remaining triplets if early stop produced fewer than k
            if (kOut < k)
            {
                converged = false;
                for (int t = kOut; t < k; t++)
                {
                    Sk[t] = (double)0;
                    for (int i = 0; i < m; i++) Uk[i, t] = (double)0;
                    for (int i = 0; i < n; i++) Vk[i, t] = (double)0;
                }
            }

            return new SVDInfo
            {
                status = converged ? IterativeSolveStatus.Converged : IterativeSolveStatus.MaxIterations,
                sweeps = innerSweeps,
                converged = innerConverged
            };
        }

        /// <summary>truncated (ref workspace) with default partialReorth=true.</summary>
        public static SVDInfo truncated(in doubleMxN A, ref doubleMxN Uk, ref doubleN Sk, ref doubleMxN Vk,
                                        int k, int oversample, uint seed, int maxIterations,
                                        ref doubleSVDTruncatedCache ws)
            => truncated(in A, ref Uk, ref Sk, ref Vk, k, oversample, seed, maxIterations, true, ref ws);

        /// <summary>truncated (ref workspace) with default maxIterations (Consts.sweepBudget(p), p = min(k+oversample, A.N_Cols)) and partialReorth=true.</summary>
        public static SVDInfo truncated(in doubleMxN A, ref doubleMxN Uk, ref doubleN Sk, ref doubleMxN Vk,
                                        int k, int oversample, uint seed,
                                        ref doubleSVDTruncatedCache ws)
            => truncated(in A, ref Uk, ref Sk, ref Vk, k, oversample, seed,
                         Consts.sweepBudget(math.min(k + oversample, A.N_Cols)), true, ref ws);

        /// <summary>truncated (ref workspace) with default seed, default maxIterations (Consts.sweepBudget(p)) and partialReorth=true.</summary>
        public static SVDInfo truncated(in doubleMxN A, ref doubleMxN Uk, ref doubleN Sk, ref doubleMxN Vk,
                                        int k, int oversample,
                                        ref doubleSVDTruncatedCache ws)
            => truncated(in A, ref Uk, ref Sk, ref Vk, k, oversample, 0x9E3779B1u,
                         Consts.sweepBudget(math.min(k + oversample, A.N_Cols)), true, ref ws);

        /// <summary>
        /// truncated (ref workspace) with generous default Krylov width p = min(n, max(2k, k+12)),
        /// default maxIterations (Consts.sweepBudget(p)) and partialReorth=true.
        /// Pass a workspace from Arena.doubleSVDTruncatedCache(m, n, k) (no oversample overload)
        /// which uses the same generous formula.
        /// </summary>
        public static SVDInfo truncated(in doubleMxN A, ref doubleMxN Uk, ref doubleN Sk, ref doubleMxN Vk,
                                        int k, ref doubleSVDTruncatedCache ws)
            => truncated(in A, ref Uk, ref Sk, ref Vk, k, math.max(k, 12), 0x9E3779B1u,
                         Consts.sweepBudget(math.min(A.N_Cols, math.max(2 * k, k + 12))), true, ref ws);

        /// <summary>
        /// truncated allocating all scratch from A's arena (explicit oversample/seed/maxIterations/partialReorth).
        /// See the ref-workspace overload for semantics.
        /// </summary>
        public static SVDInfo truncated(in doubleMxN A, ref doubleMxN Uk, ref doubleN Sk, ref doubleMxN Vk,
                                        int k, int oversample, uint seed, int maxIterations, bool partialReorth)
        {
            int m = A.M_Rows;
            int n = A.N_Cols;
            if (k < 0 || k > n) throw new ArgumentException("truncated: k must be in [0, A.N_Cols]");
            if (oversample < 0) throw new ArgumentException("truncated: oversample must be >= 0");
            int p = math.min(k + oversample, n);
            var ws = new doubleSVDTruncatedCache
            {
                UL     = A.doubleTempMat(p, m),
                VL     = A.doubleTempMat(p + 1, n),
                dB     = A.doubleTempVec(p),
                eB     = A.doubleTempVec(p),
                UtB    = A.doubleTempMat(p, p),
                VtB    = A.doubleTempMat(p, p),
                BsvdWs = new doubleSVDFullCache
                {
                    U = A.doubleTempMat(p, p),
                    S = A.doubleTempVec(p),
                    V = A.doubleTempMat(p, p)
                },
                uBuf  = A.doubleTempVec(m),
                vBuf  = A.doubleTempVec(n),
                alpha = A.doubleTempVec(p),
                beta  = A.doubleTempVec(p),
                mu    = A.doubleTempVec(p + 1),
                nu    = A.doubleTempVec(p + 1)
            };
            return truncated(in A, ref Uk, ref Sk, ref Vk, k, oversample, seed, maxIterations, partialReorth, ref ws);
        }

        /// <summary>
        /// truncated allocating all scratch from A's arena (explicit oversample/seed/maxIterations),
        /// with default partialReorth=true.
        /// See the ref-workspace overload for semantics.
        /// </summary>
        public static SVDInfo truncated(in doubleMxN A, ref doubleMxN Uk, ref doubleN Sk, ref doubleMxN Vk,
                                        int k, int oversample, uint seed, int maxIterations)
        {
            int m = A.M_Rows;
            int n = A.N_Cols;
            if (k < 0 || k > n) throw new ArgumentException("truncated: k must be in [0, A.N_Cols]");
            if (oversample < 0) throw new ArgumentException("truncated: oversample must be >= 0");
            int p = math.min(k + oversample, n);
            var ws = new doubleSVDTruncatedCache
            {
                UL     = A.doubleTempMat(p, m),
                VL     = A.doubleTempMat(p + 1, n),
                dB     = A.doubleTempVec(p),
                eB     = A.doubleTempVec(p),
                UtB    = A.doubleTempMat(p, p),
                VtB    = A.doubleTempMat(p, p),
                BsvdWs = new doubleSVDFullCache
                {
                    U = A.doubleTempMat(p, p),
                    S = A.doubleTempVec(p),
                    V = A.doubleTempMat(p, p)
                },
                uBuf  = A.doubleTempVec(m),
                vBuf  = A.doubleTempVec(n),
                alpha = A.doubleTempVec(p),
                beta  = A.doubleTempVec(p),
                mu    = A.doubleTempVec(p + 1),
                nu    = A.doubleTempVec(p + 1)
            };
            return truncated(in A, ref Uk, ref Sk, ref Vk, k, oversample, seed, maxIterations, true, ref ws);
        }

        /// <summary>
        /// truncated (allocating) with generous default Krylov width p = min(n, max(2k, k+12)),
        /// default seed (0x9E3779B1u), default maxIterations (Consts.sweepBudget(p)), and default
        /// partialReorth=true.
        /// </summary>
        public static SVDInfo truncated(in doubleMxN A, ref doubleMxN Uk, ref doubleN Sk, ref doubleMxN Vk,
                                        int k)
        {
            int m = A.M_Rows;
            int n = A.N_Cols;
            if (k < 0 || k > n) throw new ArgumentException("truncated: k must be in [0, A.N_Cols]");
            int p = math.min(n, math.max(2 * k, k + 12));
            var ws = new doubleSVDTruncatedCache
            {
                UL     = A.doubleTempMat(p, m),
                VL     = A.doubleTempMat(p + 1, n),
                dB     = A.doubleTempVec(p),
                eB     = A.doubleTempVec(p),
                UtB    = A.doubleTempMat(p, p),
                VtB    = A.doubleTempMat(p, p),
                BsvdWs = new doubleSVDFullCache
                {
                    U = A.doubleTempMat(p, p),
                    S = A.doubleTempVec(p),
                    V = A.doubleTempMat(p, p)
                },
                uBuf  = A.doubleTempVec(m),
                vBuf  = A.doubleTempVec(n),
                alpha = A.doubleTempVec(p),
                beta  = A.doubleTempVec(p),
                mu    = A.doubleTempVec(p + 1),
                nu    = A.doubleTempVec(p + 1)
            };
            // Use oversample = max(k, 12) which gives p = min(k + max(k,12), n) = min(max(2k,k+12), n)
            return truncated(in A, ref Uk, ref Sk, ref Vk, k, math.max(k, 12), 0x9E3779B1u, Consts.sweepBudget(p), true, ref ws);
        }

        /// <summary>
        /// Best rank-k approximation of A (m x n, m >= n) written into Ak (m x n, caller-allocated):
        /// Ak = Σ_{t&lt;k} σ_t u_t v_tᵀ = Uk diag(Sk) Vkᵀ. This is the matrix that minimizes
        /// ||A - Ak|| over all rank-k matrices (Eckart-Young); the Frobenius error is sqrt(Σ_{i&gt;=k} σ_i²).
        /// Uses the FULL Golub-Kahan SVD (thin) internally — EXACT, not approximate. 0 &lt;= k &lt;= n.
        /// A is NOT modified. Returns the inner SVD's <see cref="SVDInfo"/> (implicit-bool ==
        /// Converged); on MaxIterations Ak is zeroed but NOT a valid approximation.
        /// <paramref name="ws"/> is full-SVD scratch reused across calls; size it with
        /// Arena.doubleSVDFullCache(m, n).
        /// </summary>
        public static SVDInfo lowRankApprox(in doubleMxN A, ref doubleMxN Ak, int k,
                                         ref doubleSVDFullCache ws, int maxIterations)
        {
            int m = A.M_Rows;
            int n = A.N_Cols;

            if (m < n)
                throw new ArgumentException("lowRankApprox: A must have m >= n (more rows than columns)");
            if (k < 0 || k > n)
                throw new ArgumentException("lowRankApprox: k must be in [0, A.N_Cols]");
            if (Ak.M_Rows != m || Ak.N_Cols != n)
                throw new ArgumentException("lowRankApprox: Ak must be m x n");
            if (maxIterations < 1)
                throw new ArgumentException("lowRankApprox: maxIterations must be >= 1");
            RequireSvdFullWorkspace(in ws, m, n);

            // Ak starts at zero (rank 0); also the correct result for k == 0 / empty A.
            for (int i = 0; i < m; i++)
                for (int j = 0; j < n; j++)
                    Ak[i, j] = (double)0;

            if (n == 0 || k == 0)
                return new SVDInfo { status = IterativeSolveStatus.Converged, sweeps = 0, converged = 0 };

            SVDInfo info = thin(in A, ref ws.U, ref ws.S, ref ws.V, maxIterations);
            if (!info)
                return info;

            // Ak += σ_t · u_t v_tᵀ for t < k
            for (int t = 0; t < k; t++)
            {
                double s = ws.S[t];
                for (int i = 0; i < m; i++)
                {
                    double us = ws.U[i, t] * s;
                    for (int j = 0; j < n; j++)
                        Ak[i, j] += us * ws.V[j, t];
                }
            }

            return info;
        }

        /// <summary>lowRankApprox (ref workspace) with default maxIterations (Consts.sweepBudget(A.N_Cols)).</summary>
        public static SVDInfo lowRankApprox(in doubleMxN A, ref doubleMxN Ak, int k,
                                         ref doubleSVDFullCache ws)
            => lowRankApprox(in A, ref Ak, k, ref ws, Consts.sweepBudget(A.N_Cols));

        /// <summary>
        /// lowRankApprox allocating its full-SVD scratch from A's arena.
        /// See the ref-workspace overload for semantics.
        /// </summary>
        public static SVDInfo lowRankApprox(in doubleMxN A, ref doubleMxN Ak, int k, int maxIterations)
        {
            int m = A.M_Rows;
            int n = A.N_Cols;
            var ws = new doubleSVDFullCache
            {
                U = A.doubleTempMat(m, n),
                S = A.doubleTempVec(n),
                V = A.doubleTempMat(n, n)
            };
            return lowRankApprox(in A, ref Ak, k, ref ws, maxIterations);
        }

        /// <summary>lowRankApprox (allocating) with default maxIterations (Consts.sweepBudget(A.N_Cols)).</summary>
        public static SVDInfo lowRankApprox(in doubleMxN A, ref doubleMxN Ak, int k)
            => lowRankApprox(in A, ref Ak, k, Consts.sweepBudget(A.N_Cols));
    }
